
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_kcisk_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_kcisk", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.458228379094540e-02, -4.411339223546719e-02, -4.343977744954801e-02, -4.247277483676775e-02, -4.108665516730042e-02, -3.910652233337506e-02, -3.630266709866956e-02, -3.242876748676113e-02, -2.744033375406056e-02, -2.223978531015530e-02, -2.121068478033621e-02, -4.138895134307696e-02, -4.339369924975524e-02, -2.867459788308399e-02, -1.858671630639083e-02, -8.423814220732719e-03, -2.062559245130599e-03, -2.054488943890537e-04, -3.953364666150490e-06, -1.359273879065376e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


